rule yaml.github-actions.security.curl-eval.curl-eval: metavariable-pattern failed when parsing $SHELL's content as Bash: $map = @{ 'semgrep.json' = 'Semgrep JSON Report'; 'trivy-config.json' = 'Trivy Scan';
          'trivy-fs.json' = 'Trivy Scan'; 'trivy-image.json' = 'Trivy Scan' }
foreach ($file in $map.Keys) {
  $path = Join-Path reports $file
  if (Test-Path $path) {
    ./scripts/import-defectdojo.ps1 -ReportPath $path -ScanType $map[$file] -EngagementId ([int]$env:ENGAGEMENT)
  }
}

